-- cash-cents-v1: new execution proof only. Historical NULL values are not backfilled.
-- Explicit guarded migration only; no alteration of DECIMAL money, prices or quantities.
SET @unexpected := (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE IN ('sale_orders','sale_returns','sale_ordinary_return_receipts','purchase_orders','purchase_returns','payment_records'));
-- Only the two unchanged standard party-ledger triggers from migration 241.
SET @known := (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='payment_records' AND ACTION_TIMING='AFTER' AND ACTION_ORIENTATION='ROW' AND ACTION_CONDITION IS NULL AND ((TRIGGER_NAME='trg_party_ledger_record_insert' AND EVENT_MANIPULATION='INSERT' AND SHA2(ACTION_STATEMENT,256)='73fb463eba2a190e2442fe03eb29409a48cbc32111a894498a72e27c3ee788cf') OR (TRIGGER_NAME='trg_party_ledger_record_update' AND EVENT_MANIPULATION='UPDATE' AND SHA2(ACTION_STATEMENT,256)='5c8390563b15a425f40bd01301d34821de8320c57daa568cebc74452e0db5514')));
SET @sql := IF(@unexpected=2 AND @known=2, 'SELECT 1', 'SELECT * FROM __cash_cents_292_unexpected_trigger__');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql := IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sale_orders' AND COLUMN_NAME='cash_policy'), 'SELECT 1', 'ALTER TABLE sale_orders ADD COLUMN cash_policy VARCHAR(30) CHARACTER SET ascii COLLATE ascii_bin NULL');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ok := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sale_orders' AND COLUMN_NAME='cash_policy' AND COLUMN_TYPE='varchar(30)' AND CHARACTER_SET_NAME='ascii' AND COLLATION_NAME='ascii_bin' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='');
SET @sql := IF(@ok=1, 'SELECT 1', 'SELECT * FROM __cash_cents_292_sale_orders_cash_policy_shape_mismatch__');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
